import pickle
import time

class SessionCache:
    def __init__(self, ttl_seconds=3600):
        self.cache = {}
        self.ttl_seconds = ttl_seconds
        self.timestamps = {}

    def set_session(self, user_id, session_data):
        """Store session object in cache using pickle for speed."""
        self.cache[user_id] = pickle.dumps(session_data)
        self.timestamps[user_id] = time.time()

    def get_session(self, user_id):
        """Retrieve and deserialize session from cache."""
        if user_id not in self.cache:
            return None

        # Check TTL
        if time.time() - self.timestamps[user_id] > self.ttl_seconds:
            del self.cache[user_id]
            del self.timestamps[user_id]
            return None

        # Deserialize and return
        return pickle.loads(self.cache[user_id])

    def clear_session(self, user_id):
        """Remove session from cache."""
        if user_id in self.cache:
            del self.cache[user_id]
            del self.timestamps[user_id]

# Example usage
if __name__ == "__main__":
    cache = SessionCache()
    user_session = {"user_id": 123, "username": "alice", "roles": ["admin"]}
    cache.set_session("alice", user_session)
    retrieved = cache.get_session("alice")
    print(retrieved)
